const rows = $input.all().map((i) => i.json);
const trigger = $('Digest Trigger').first().json;
const days = (trigger.body || trigger).days || 7;

const totalRuns = rows.reduce((sum, r) => sum + Number(r.runs), 0);
const totalErrors = rows.reduce((sum, r) => sum + Number(r.errors), 0);

const lines = rows.map((r) => {
  const icon = Number(r.errors) > 0 ? ':x:' : ':white_check_mark:';
  return icon + ' *' + r.workflow + '* -- ' + r.runs + ' runs, ' + r.errors + ' errors (' + r.error_rate_pct + '%), avg ' + r.avg_runtime_seconds + 's, last ' + r.last_run_at;
});

const digest = ':bar_chart: *Support Ops Digest (last ' + days + ' days)*\n' +
  '*Total:* ' + totalRuns + ' runs, ' + totalErrors + ' errors across ' + rows.length + ' workflows\n' +
  (lines.length ? lines.join('\n') : '_No executions in this window._');

return [{
  json: {
    window_days: Number(days),
    workflows_reported: rows.length,
    total_runs: totalRuns,
    total_errors: totalErrors,
    stats: rows,
    slack_channel: '#support-ops',
    slack_text: digest,
  },
}];
